#!/usr/bin/env python3
"""SEO check of the HTML files generated by a build (prerender, SSG, static site), before deploy.

Reads every .html file in the output folder with the same parser as seo_fetch.py
and reports, per URL: title and description (missing, duplicate), canonical
(missing, multiple, not the page URL, pointing to the home page, localhost or
staging host, http://, relative), H1 count, JSON-LD validity, lang, viewport,
noindex, near-empty pages, size over 2 MB, broken internal links between the
generated files, links to localhost/staging hosts and http:// assets. Site level:
robots.txt (and Disallow: /), sitemap files and the sitemap vs pages difference.

Usage:
  python check_build.py dist/browser --base https://acme-widgets.example
  python check_build.py out --base https://acme-widgets.example --fail-on medium --json build-check.json

Exit codes: 0 no finding at or above --fail-on · 1 findings at or above --fail-on
(default high) · 2 usage error.
"""
import argparse
import fnmatch
import os
import re
import sys
import urllib.parse
from pathlib import Path


def _bootstrap():
    """Put <plugin>/lib on sys.path (walks up from this file to find lib/seokit)."""
    here = os.path.dirname(os.path.abspath(__file__))
    while True:
        if os.path.isdir(os.path.join(here, "lib", "seokit")):
            sys.path.insert(0, os.path.join(here, "lib"))
            return
        parent = os.path.dirname(here)
        if parent == here:
            sys.stderr.write("seo-kit: cannot find the lib/seokit folder of the plugin\n")
            sys.exit(2)
        here = parent


_bootstrap()

from seokit import __version__, report, robots, sitemap, typos, urls  # noqa: E402
from seokit import html as seohtml  # noqa: E402
from seokit import http as seohttp  # noqa: E402

SEVERITIES = ("low", "medium", "high", "critical")
LABEL = {"low": "Low", "medium": "Medium", "high": "High", "critical": "Critical"}
SKIP_DIRS = {"node_modules", ".git"}
# Framework or verification files: informational, not indexable pages.
SHELL_FILES = ("index.csr.html", "200.html", "404.html", "_fallback.html", "google*.html", "BingSiteAuth.xml")
GOOGLE_HTML_LIMIT = 2 * 1024 * 1024
NEAR_EMPTY_CHARS = 300
LOCAL_HOSTS = {"localhost", "127.0.0.1", "0.0.0.0", "::1", "[::1]"}
STAGING_RE = re.compile(r"(^|[.-])(staging|stage|dev|test|preview|uat|qa)([.-]|$)|"
                        r"\.(vercel\.app|netlify\.app|pages\.dev|onrender\.com|herokuapp\.com)$", re.I)
HTTP_ASSET_RE = re.compile(r"""\s(?:src|srcset|poster|data-src)\s*=\s*["']\s*(http://[^"'\s,]+)""", re.I)
HTTP_LINK_TAG_RE = re.compile(r"<link\b[^>]*>", re.I)


def is_shell(name):
    return any(fnmatch.fnmatch(name, pattern) for pattern in SHELL_FILES)


def finding(severity, check, message):
    return {"severity": severity, "check": check, "message": message}


def page_url(base, root, path):
    """URL of a generated file: <dir>/index.html -> <dir>/, other .html files keep their path."""
    rel = path.relative_to(root).as_posix()
    if path.name == "index.html":
        rel = rel[: -len("index.html")]
    return base.rstrip("/") + "/" + urllib.parse.quote(rel, safe="/%:@!$&'()*+,;=~")


def same_page(url, page):
    """True when url addresses the page; X.html also answers as X (clean URLs, e.g. Next.js export)."""
    key = urls.compare_key(url)
    if key == urls.compare_key(page):
        return True
    return page.endswith(".html") and key == urls.compare_key(page[: -len(".html")])


def bad_host(host, base_host):
    """'localhost' / 'staging' when a URL host should never appear in production HTML."""
    host = (host or "").lower()
    if host == base_host:
        return None
    if host in LOCAL_HOSTS or host.endswith(".local") or host.endswith(".localhost"):
        return "localhost"
    if STAGING_RE.search(host):
        return "staging"
    return None


def find_root(root):
    """Angular writes dist/<project>/browser/: use it when the given folder has no index.html."""
    if (root / "index.html").exists():
        return root
    for depth_glob in ("browser", "*/browser", "*/*/browser"):
        for cand in sorted(root.glob(depth_glob)):
            if (cand / "index.html").exists():
                return cand
    return root


def list_files(root):
    out = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]
        for name in filenames:
            out.append(Path(dirpath) / name)
    return sorted(out)


class Site:
    def __init__(self, root, base):
        self.root = root
        self.base = base.rstrip("/") + "/"
        parts = urllib.parse.urlsplit(self.base)
        self.base_scheme = parts.scheme
        self.base_host = (parts.hostname or "").lower()
        self.base_path = parts.path
        self.base_site = urls.site_key(self.base)
        self.files = {p.relative_to(root).as_posix() for p in list_files(root)}

    def local_target(self, url):
        """Relative file path an internal URL maps to, '' for an unknown target, None if external."""
        if urls.site_key(url) != self.base_site:
            return None
        path = urllib.parse.unquote(urllib.parse.urlsplit(url).path)
        if not path.startswith(self.base_path):
            return None
        rel = path[len(self.base_path):]
        candidates = [rel + "index.html"] if rel == "" or rel.endswith("/") else [rel, rel + ".html", rel + "/index.html"]
        for cand in candidates:
            if cand in self.files:
                return cand
        return ""


def analyze(path, url, site, lang_arg):
    raw = path.read_bytes()
    text = seohttp.decode_text(raw, "")[0]
    page = seohtml.parse_page(text, url)
    rel = path.relative_to(site.root).as_posix()
    noindex = any("noindex" in r for r in page["indexable"]["reasons"])
    out = {"url": url, "file": rel, "shell": False, "noindex": noindex, "bytes": len(raw),
           "title": page["title"], "meta_description": page["meta_description"], "lang": page["lang"],
           "canonical": page["canonical"]["resolved"], "h1": page["h1"],
           "main_text_chars": page["main_text_chars"], "jsonld_types": page["jsonld_types"], "findings": []}
    f = out["findings"]
    if is_shell(path.name):
        out["shell"] = True
        msg = ("custom 404 page: the server must answer HTTP 404 (not 200) when it serves it"
               if path.name == "404.html" else
               "framework fallback or verification file: it must not be served for indexable URLs")
        f.append(finding("low", "shell-file", msg))
        return out, page
    if len(raw) > GOOGLE_HTML_LIMIT:
        f.append(finding("high", "html-over-2mb", f"{len(raw) // 1024} KiB of HTML: Googlebot reads only the first 2 MB"))
    if noindex:
        f.append(finding("low", "noindex", "page has noindex: check that this is intended"))
        return out, page

    if not page["title"] or not page["title"][0]:
        f.append(finding("high", "title-missing", "title missing or empty"))
    elif len(page["title"]) > 1:
        f.append(finding("medium", "title-multiple", f"{len(page['title'])} <title> elements"))
    if not page["meta_description"] or not page["meta_description"][0]:
        f.append(finding("medium", "description-missing", "meta description missing or empty"))

    canon = page["canonical"]
    if canon["count"] == 0:
        f.append(finding("medium", "canonical-missing", "no canonical link"))
    else:
        if canon["count"] > 1:
            f.append(finding("high", "canonical-multiple", f"{canon['count']} canonical links: {canon['all']}"))
        if canon["in_body"]:
            f.append(finding("high", "canonical-in-body", "canonical is in <body>: Google ignores it there"))
        href = (canon["href"] or "").strip()
        resolved = canon["resolved"] or ""
        host = (urllib.parse.urlsplit(resolved).hostname or "").lower()
        kind = bad_host(host, site.base_host)
        if not href:
            f.append(finding("high", "canonical-empty", "canonical href is empty"))
        elif kind:
            f.append(finding("high", "canonical-bad-host", f"canonical points to a {kind} host: {resolved}"))
        elif urls.scheme_of(href) == "http" and site.base_scheme == "https":
            f.append(finding("high", "canonical-http", f"canonical uses http:// on an https site: {href}"))
        elif not same_page(resolved, url):
            if urls.compare_key(resolved) == urls.compare_key(site.base) and urls.compare_key(url) != urls.compare_key(site.base):
                f.append(finding("high", "canonical-to-home", f"canonical points to the home page instead of {url}"))
            else:
                f.append(finding("high", "canonical-mismatch", f"canonical {resolved} is not the page URL {url}"))
        if href and not urls.scheme_of(href) and not href.startswith("//"):
            f.append(finding("low", "canonical-relative", f"relative canonical {href!r}: use an absolute URL"))

    if not page["h1"]:
        f.append(finding("medium", "h1-missing", "no H1"))
    elif len(page["h1"]) > 1:
        f.append(finding("low", "h1-multiple", f"{len(page['h1'])} H1 elements"))
    for err in page["jsonld_errors"]:
        sev = "low" if err["recovered"] else "high"
        f.append(finding(sev, "jsonld-invalid", f"JSON-LD block {err['index']}: {err['error']}"))
    if not page["lang"]:
        f.append(finding("low", "lang-missing", "no lang attribute on <html>"))
    if not page["viewport"]:
        f.append(finding("medium", "viewport-missing", "no <meta name=\"viewport\">: the page is not mobile-ready"))
    if page["head_invalid_tags"]:
        f.append(finding("medium", "head-invalid-tags",
                         f"elements that close <head> early: {page['head_invalid_tags']}; later meta tags may be ignored"))
    if page["main_text_chars"] < NEAR_EMPTY_CHARS:
        f.append(finding("medium", "near-empty",
                         f"only {page['main_text_chars']} characters of main text: not prerendered, or an empty shell?"))
    if page["heading_skips"]:
        skips = ", ".join(f"{s['from']}->{s['to']}" for s in page["heading_skips"])
        f.append(finding("low", "heading-skips", f"heading levels skipped: {skips}"))

    broken, bad_links = [], []
    for link in page["internal_links"] + page["external_links"]:
        host = (urllib.parse.urlsplit(link["resolved"]).hostname or "").lower()
        kind = bad_host(host, site.base_host)
        if kind:
            bad_links.append(link["resolved"])
            continue
        if site.local_target(link["resolved"]) == "":
            broken.append(link["href"])
    if broken:
        uniq = list(dict.fromkeys(broken))
        f.append(finding("medium", "broken-internal-links",
                         f"{len(uniq)} internal link(s) with no generated file: {uniq[:10]}"))
    if bad_links:
        uniq = list(dict.fromkeys(bad_links))
        f.append(finding("high", "links-to-dev-hosts", f"links to localhost or staging hosts: {uniq[:10]}"))
    if site.base_scheme == "https":
        assets = HTTP_ASSET_RE.findall(text)
        for tag in HTTP_LINK_TAG_RE.findall(text):
            rel_m = re.search(r"""\brel\s*=\s*["']?([^"'>]+)""", tag, re.I)
            rel_v = (rel_m.group(1) if rel_m else "").lower()
            href_m = re.search(r"""\bhref\s*=\s*["']\s*(http://[^"'\s]+)""", tag, re.I)
            if href_m and not ({"canonical", "alternate"} & set(rel_v.split())):
                assets.append(href_m.group(1))
        if assets:
            uniq = list(dict.fromkeys(assets))
            f.append(finding("medium", "mixed-content", f"http:// assets on an https site: {uniq[:10]}"))
    found = typos.find(page, lang_arg or page["lang"])
    for t in (found or [])[:10]:
        f.append(finding("low", "typo-suspect", f"{t['field']}: {t['match']!r} ({t['why']}) - {t['context']}"))
    return out, page


def site_checks(site, pages):
    out = []
    robots_path = site.root / "robots.txt"
    if not robots_path.exists():
        out.append(finding("low", "robots-missing", "no robots.txt in the output (Google then crawls everything)"))
    else:
        parsed = robots.parse(robots_path.read_bytes())
        if not robots.is_allowed(parsed, "Googlebot", "/"):
            out.append(finding("critical", "robots-disallow-all",
                               "robots.txt blocks Googlebot from the whole site (Disallow: /)"))
    sitemap_files = sorted(p for p in site.root.glob("sitemap*.xml*") if p.is_file())
    indexable = [p for p in pages if not p["shell"] and not p["noindex"]]
    if not sitemap_files:
        out.append(finding("low", "sitemap-missing", "no sitemap*.xml in the output folder"))
    else:
        locs = []
        for path in sitemap_files:
            data = path.read_bytes()
            if data[:2] == sitemap.GZIP_MAGIC:
                data = sitemap.gunzip(data)[0]
            parsed = sitemap.parse_xml(data)
            if parsed["error"]:
                out.append(finding("high", "sitemap-invalid", f"{path.name}: {parsed['error']}"))
            locs.extend(u["loc"] for u in parsed["urls"])
        other_host = [l for l in locs if urls.site_key(l) != site.base_site]
        if other_host:
            out.append(finding("high", "sitemap-other-host",
                               f"{len(other_host)} sitemap URL(s) not on {site.base_host}: {other_host[:5]}"))
        missing = [p["url"] for p in indexable if not any(same_page(l, p["url"]) for l in locs)]
        extra = [l for l in locs if l not in other_host and not any(same_page(l, p["url"]) for p in indexable)]
        if missing:
            out.append(finding("low", "sitemap-missing-pages",
                               f"{len(missing)} generated page(s) not in the sitemap: {missing[:10]}"))
        if extra:
            out.append(finding("medium", "sitemap-extra-urls",
                               f"{len(extra)} sitemap URL(s) with no generated page (404 or server-rendered?): {extra[:10]}"))
    for key in ("title", "meta_description"):
        seen = {}
        for p in indexable:
            for value in p[key][:1]:
                if value:
                    seen.setdefault(value, []).append(p["url"])
        for value, where in seen.items():
            if len(where) > 1:
                out.append(finding("medium", f"{key.replace('_', '-')}-duplicate",
                                   f"{len(where)} pages share the {key.replace('_', ' ')} {value[:80]!r}: {where[:10]}"))
    langs = sorted({p["lang"] for p in indexable if p["lang"]})
    if len(langs) > 1:
        out.append(finding("low", "lang-inconsistent", f"pages use different lang values: {langs} "
                           "(fine for a multilingual site, otherwise a template error)"))
    inner = [p for p in indexable if urls.compare_key(p["url"]) != urls.compare_key(site.base)]
    to_home = [p for p in inner if any(f["check"] == "canonical-to-home" for f in p["findings"])]
    if len(inner) >= 2 and len(to_home) == len(inner):
        out.append(finding("critical", "canonical-home-everywhere",
                           f"all {len(inner)} inner pages declare the home page as canonical: they can drop out of the index"))
    return out


def build_parser():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("dir", help="build output folder")
    ap.add_argument("--base", required=True, help="production URL, e.g. https://acme-widgets.example")
    ap.add_argument("--fail-on", choices=SEVERITIES, default="high",
                    help="exit 1 when a finding has this severity or higher (default: high)")
    ap.add_argument("--json", metavar="PATH", help="also write the full result as JSON")
    ap.add_argument("--lang", metavar="xx", help="language for the optional typo pack (default: each page's lang)")
    ap.add_argument("--version", action="version", version=f"seo-kit {__version__}")
    return ap


def main(argv=None):
    report.setup_stdout()
    args = build_parser().parse_args(argv)
    try:
        base = urls.normalize_url(args.base)
    except urls.InvalidURL as exc:
        report.eprint(f"error: --base: {exc}")
        return 2
    root = Path(args.dir)
    if not root.is_dir():
        report.eprint(f"error: {args.dir} is not a folder")
        return 2
    root = find_root(root.resolve())
    site = Site(root, base)
    html_files = [p for p in list_files(root) if p.suffix.lower() in (".html", ".htm")]
    if not html_files:
        report.eprint(f"error: no .html files in {root}")
        return 2
    pages = [analyze(p, page_url(site.base, root, p), site, args.lang)[0] for p in html_files]
    site_findings = site_checks(site, pages)
    shell_extra = [n for n in sorted(site.files) if "/" not in n and is_shell(n) and not n.endswith(".html")]

    threshold = SEVERITIES.index(args.fail_on)
    all_findings = site_findings + [f for p in pages for f in p["findings"]]
    counts = {s: sum(1 for f in all_findings if f["severity"] == s) for s in SEVERITIES}
    failing = sum(1 for f in all_findings if SEVERITIES.index(f["severity"]) >= threshold)
    exit_code = 1 if failing else 0
    result = {"tool": "check_build", "version": __version__, "dir": str(root), "base": site.base,
              "fail_on": args.fail_on, "pages": pages, "site_findings": site_findings,
              "verification_files": shell_extra, "summary": counts, "exit_code": exit_code}
    if args.json:
        report.write_json(args.json, result)

    print(f"check_build: {len(pages)} HTML files in {root} (base {site.base})\n")
    width = max(len(p["url"]) for p in pages)
    print(f"{'URL'.ljust(width)}  Crit  High  Med  Low  File")
    for p in pages:
        c = {s: sum(1 for f in p["findings"] if f["severity"] == s) for s in SEVERITIES}
        print(f"{p['url'].ljust(width)}  {c['critical']:>4}  {c['high']:>4}  {c['medium']:>3}  {c['low']:>3}  {p['file']}")
    for sev in reversed(SEVERITIES):
        rows = [(None, f) for f in site_findings if f["severity"] == sev]
        rows += [(p, f) for p in pages for f in p["findings"] if f["severity"] == sev]
        if not rows:
            continue
        print(f"\n## {LABEL[sev]}")
        for p, f in rows:
            where = "site" if p is None else f"{p['url']} ({p['file']})"
            print(f"- [{LABEL[sev]}] {where} · {f['check']}: {f['message']}")
    summary = ", ".join(f"{counts[s]} {LABEL[s].lower()}" for s in reversed(SEVERITIES))
    print(f"\nResult: {summary}. Exit {exit_code} (--fail-on {args.fail_on}).")
    return exit_code


if __name__ == "__main__":
    sys.exit(main())
